package com.example.starter.support;

import org.junit.jupiter.api.BeforeEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.simple.JdbcClient;

/**
 * 集成测试基类：使用独立 H2 内存库（MODE=MySQL），每个用例前清理业务数据，避免顺序依赖。
 * 核素种子表保留（半衰期参数唯一来源）。
 */
@SpringBootTest
public abstract class BaseIntegrationTest {

    @Autowired
    protected JdbcClient jdbc;

    /**
     * 清理业务表（按外键依赖顺序），保留核素种子数据。
     */
    @BeforeEach
    void cleanBusinessTables() {
        jdbc.sql("DELETE FROM measurement").update();
        jdbc.sql("DELETE FROM ledger").update();
        jdbc.sql("DELETE FROM delivery").update();
        jdbc.sql("DELETE FROM dispense_check").update();
        jdbc.sql("DELETE FROM dispense").update();
        jdbc.sql("DELETE FROM daily_check").update();
        jdbc.sql("DELETE FROM mother_liquor").update();
        jdbc.sql("DELETE FROM reference_source").update();
        jdbc.sql("DELETE FROM dose_calibrator").update();
    }

    /**
     * 查询合成核素 TEST-1H（半衰期 3600 秒）主键，便于整点复算。
     */
    protected long testNuclideId() {
        return jdbc.sql("SELECT id FROM nuclide WHERE name = 'TEST-1H'")
                .query(Long.class).single();
    }
}

package com.example.starter.decay;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

import java.time.Instant;

import org.junit.jupiter.api.Test;

/**
 * 衰变公式单元测试：A(t) = A0 * 2^(-(t - t0) / T)。
 */
class DecayServiceTest {

    private final DecayService decayService = new DecayService();

    @Test
    void 经过一个半衰期活度减半() {
        Instant t0 = Instant.parse("2026-09-26T00:00:00Z");
        Instant t1 = Instant.parse("2026-09-26T01:00:00Z");
        assertThat(decayService.decayTo(1000.0, t0, t1, 3600)).isEqualTo(500.0);
    }

    @Test
    void 经过两个半衰期活度为四分之一() {
        Instant t0 = Instant.parse("2026-09-26T00:00:00Z");
        Instant t2 = Instant.parse("2026-09-26T02:00:00Z");
        assertThat(decayService.decayTo(1000.0, t0, t2, 3600)).isEqualTo(250.0);
    }

    @Test
    void 不足一个半衰期按指数推算() {
        Instant t0 = Instant.parse("2026-09-26T00:00:00Z");
        Instant t1 = Instant.parse("2026-09-26T00:30:00Z");
        assertThat(decayService.decayTo(1000.0, t0, t1, 3600))
                .isCloseTo(1000.0 * Math.pow(2.0, -0.5), within(1e-9));
    }

    @Test
    void 同一时刻活度不变() {
        Instant t0 = Instant.parse("2026-09-26T00:00:00Z");
        assertThat(decayService.decayTo(1000.0, t0, t0, 3600)).isEqualTo(1000.0);
    }
}

