                                + "\"measuredAt\":\"2026-09-26T09:05:00Z\"}"))
                .andExpect(status().isAccepted())
                .andExpect(jsonPath("$.late", is(true)));
    }

    @Test
    void 分装偏差超限返回422且批次为拒绝终态() throws Exception {
        seed();
        mockMvc.perform(post("/api/dispenses")
